export function resolveCloudinaryUrl(imgPathOrSlug?: string, slugHint?: string): string | null {
  if (!imgPathOrSlug && !slugHint) return null;

  const key1 = (imgPathOrSlug || "").trim();
  const key2 = (slugHint || "").trim();

  if (key1.startsWith("http://") || key1.startsWith("https://") || key1.startsWith("data:")) {
    return key1;
  }

  const filename = key1.split("/").pop() || "";
  const baseName = filename.replace(/\.(jpg|jpeg|png|svg|webp)$/i, "");

  // Check direct lookup
  if (CLOUDINARY_ASSETS_MAP[filename]) return CLOUDINARY_ASSETS_MAP[filename];
  if (CLOUDINARY_ASSETS_MAP[filename.toLowerCase()]) return CLOUDINARY_ASSETS_MAP[filename.toLowerCase()];
  if (CLOUDINARY_ASSETS_MAP[baseName]) return CLOUDINARY_ASSETS_MAP[baseName];
  if (CLOUDINARY_ASSETS_MAP[baseName.toLowerCase()]) return CLOUDINARY_ASSETS_MAP[baseName.toLowerCase()];

  if (key2) {
    if (CLOUDINARY_ASSETS_MAP[key2]) return CLOUDINARY_ASSETS_MAP[key2];
    if (CLOUDINARY_ASSETS_MAP[key2.toLowerCase()]) return CLOUDINARY_ASSETS_MAP[key2.toLowerCase()];
  }

  // If filename looks like an image file, build standard URL
  if (baseName && baseName.length > 1) {
    return `${CLOUDINARY_BASE_URL}/${baseName}.jpg`;
  }

  return null;
}
